#!/usr/bin/env node
/**
 * Generate tool-specific mirrors from the single sources of truth:
 *   .claude/rules/*.md        → .cursor/rules/<name>.mdc            (Cursor: globs / alwaysApply)
 *                             → .github/instructions/<name>.instructions.md (Copilot: applyTo)
 *   .claude/agents/<name>.md  → .github/agents/<name>.agent.md      (Copilot custom agent)
 *   AGENTS.md                 → .github/copilot-instructions.md     (pointer, always-on)
 *
 * Usage: node scripts/sync-agent-config.mjs [--check]
 *   --check  exit 1 if any generated file would change (CI gate)
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { basename, dirname, join } from 'node:path';

const root = process.cwd();
const check = process.argv.includes('--check');
const HEADER = '<!-- GENERATED by scripts/sync-agent-config.mjs from %s — edit the source, then run `sync:agents` -->\n';
let changed = 0;

function parseFrontmatter(text) {
  const m = text.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!m) return { data: {}, body: text };
  const data = {};
  let key = null;
  for (const line of m[1].split('\n')) {
    const kv = line.match(/^([A-Za-z_-]+):\s*(.*)$/);
    if (kv) {
      key = kv[1];
      const value = kv[2].trim();
      data[key] = value === '' ? [] : value.replace(/^"(.*)"$/, '$1');
    } else if (key && /^\s*-\s+/.test(line)) {
      if (!Array.isArray(data[key])) data[key] = [];
      data[key].push(line.replace(/^\s*-\s+/, '').trim().replace(/^"(.*)"$/, '$1'));
    }
  }
  return { data, body: m[2] };
}

function emit(relPath, content) {
  const full = join(root, relPath);
  const current = existsSync(full) ? readFileSync(full, 'utf8') : null;
  if (current === content) return;
  changed++;
  if (check) { console.log(`✖ out of date: ${relPath}`); return; }
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, content);
  console.log(`✔ wrote ${relPath}`);
}

// ---- rules → cursor + copilot instructions ----
const rulesDir = join(root, '.claude', 'rules');
if (existsSync(rulesDir)) {
  for (const file of readdirSync(rulesDir).filter((f) => f.endsWith('.md')).sort()) {
    const source = `.claude/rules/${file}`;
    const { data, body } = parseFrontmatter(readFileSync(join(rulesDir, file), 'utf8'));
    const paths = Array.isArray(data.paths) ? data.paths : data.paths ? [data.paths] : [];
    const title = (body.match(/^#\s+(.+)$/m) || [])[1] ?? basename(file, '.md');
    const name = basename(file, '.md');
    const trimmed = body.trim() + '\n';

    const cursor = paths.length
      ? `---\ndescription: ${title}\nglobs: ${paths.join(',')}\nalwaysApply: false\n---\n`
      : `---\ndescription: ${title}\nalwaysApply: true\n---\n`;
    emit(`.cursor/rules/${name}.mdc`, cursor + HEADER.replace('%s', source) + trimmed);

    const copilot = paths.length ? `---\napplyTo: "${paths.join(',')}"\n---\n` : `---\napplyTo: "**"\n---\n`;
    emit(`.github/instructions/${name}.instructions.md`, copilot + HEADER.replace('%s', source) + trimmed);
  }
}

// ---- agents → copilot custom agents ----
const agentNames = [];
const agentsDir = join(root, '.claude', 'agents');
if (existsSync(agentsDir)) {
  for (const file of readdirSync(agentsDir).filter((f) => f.endsWith('.md')).sort()) {
    const source = `.claude/agents/${file}`;
    const { data, body } = parseFrontmatter(readFileSync(join(agentsDir, file), 'utf8'));
    const name = data.name ?? basename(file, '.md');
    agentNames.push(name);
    const skills = Array.isArray(data.skills) ? data.skills : [];
    const preload = skills.length
      ? `\n## Skills\n\nBefore starting any task, load these skills from \`.claude/skills/\` (Copilot discovers them automatically): ${skills.map((s) => `\`${s}\``).join(', ')}. Load the task skill named in the routing table when you reach it.\n`
      : '';
    const content = `---\nname: ${name}\ndescription: ${data.description ?? ''}\n---\n` + HEADER.replace('%s', source) + body.trim() + '\n' + preload;
    emit(`.github/agents/${name}.agent.md`, content);
  }
}

// ---- AGENTS.md → copilot-instructions.md ----
if (existsSync(join(root, 'AGENTS.md'))) {
  const content = HEADER.replace('%s', 'AGENTS.md') +
    '# Copilot instructions\n\n' +
    'Follow `AGENTS.md` at the repository root: it is the contract for this Playwright framework (parameters, layout, non-negotiable rules, test styles).\n\n' +
    '- Path-specific rules: `.github/instructions/*.instructions.md` (generated from `.claude/rules/`).\n' +
    '- Agent skills: `.claude/skills/` (`playwright-architecture`, `playwright-scaffold`, `playwright-create-test`, `playwright-fix-test`, `playwright-delete-test`, `playwright-ci`).\n' +
    (agentNames.length ? `- Custom agent${agentNames.length > 1 ? 's' : ''}: ${agentNames.map((n) => `\`.github/agents/${n}.agent.md\``).join(', ')}.\n` : '') +
    '- Definition of done: `lint` clean and the targeted `playwright test` run green; never weaken an assertion to pass a test.\n';
  emit('.github/copilot-instructions.md', content);
}

if (check) {
  if (changed) { console.log(`\n${changed} generated file(s) out of date. Run: node scripts/sync-agent-config.mjs`); process.exit(1); }
  console.log('✔ generated agent config is up to date');
} else if (!changed) {
  console.log('✔ nothing to update');
}
